// Template: invitation_sent/fr — rendu inline (versionné dans /n8n/email-templates)
const input = $('Execute Workflow Trigger').first().json;
const payload = input.payload || input;
const d = payload.data || {};

const SUBJECT_TPL = "{{invitedByName}} vous invite \u00e0 rejoindre {{organizationName}} sur Contravo";
const BODY_MJML = "<mjml><mj-body><mj-section><mj-column>\n      <mj-text>Bonjour,</mj-text>\n      <mj-text><strong>{{invitedByName}}</strong> vous invite \u00e0 rejoindre l'espace <strong>{{organizationName}}</strong> sur Contravo en tant que {{roleLabel}}.</mj-text>\n      <mj-button href=\"{{inviteUrl}}\">Rejoindre l'\u00e9quipe</mj-button>\n      <mj-text>Ce lien est valable 7 jours et ne fonctionne qu'avec l'adresse {{email}}.</mj-text>\n      <mj-text>Si vous ne connaissez pas cette organisation, ignorez cet email.</mj-text>\n      <mj-text>Contravo</mj-text>\n    </mj-column></mj-section></mj-body></mjml>\n";

const ROLE_LABELS = {
  owner: 'propriétaire',
  admin: 'administrateur',
  member: 'membre',
  viewer: 'lecteur',
};

const ctx = {
  ...d,
  email: d.email || '',
  organizationName: d.organizationName || '',
  invitedByName: d.invitedByName || 'Un membre de l\'équipe',
  roleLabel: ROLE_LABELS[d.role] || d.role || 'membre',
  inviteUrl: d.inviteUrl || '',
};

function lookup(path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), ctx);
}
function resolve(tpl) {
  return tpl.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, p) => {
    const v = lookup(p);
    return v == null ? '' : String(v);
  });
}

// MJML -> HTML. mjml est optionnel dans l'image n8n : fallback si absent.
function compile(mjmlSource) {
  try {
    const mjml2html = require('mjml');
    const out = mjml2html(mjmlSource, { validationLevel: 'soft' });
    if (out && out.html) return out.html;
  } catch (e) {
    // mjml non installé -> dégradation contrôlée vers un HTML simple
  }
  const body = mjmlSource
    .replace(/<mj-button[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/mj-button>/g,
             '<p><a href="$1">$2</a></p>')
    .replace(/<mj-text[^>]*>([\s\S]*?)<\/mj-text>/g, '<p>$1</p>')
    .replace(/<\/?mj-(?:mjml|body|section|column|raw)[^>]*>/g, '')
    .replace(/<\/?mjml[^>]*>/g, '');
  return '<!doctype html><html><body>' + body + '</body></html>';
}

const to = [d.email].filter(Boolean);
if (!to.length) {
  throw new Error('Aucun destinataire résolu pour invitation_sent (event ' + (payload.id || '?') + ')');
}
if (!d.inviteUrl) {
  throw new Error('inviteUrl absent : une invitation sans lien est inutile');
}

return [{ json: {
  eventId: payload.id || '',
  organizationId: payload.organizationId || '',
  to,
  subject: resolve(SUBJECT_TPL).trim(),
  html: compile(resolve(BODY_MJML)),
} }];
